_TRANSLATIONS = {}
for _line in _RAW_TRANSLATIONS.splitlines():
    if not _line.strip():
        continue
    _parts = _line.split("|")
    if len(_parts) != len(LANGUAGES):
        raise RuntimeError(
            f"Translation row {_parts[0]!r} has {len(_parts)} fields; "
            f"expected {len(LANGUAGES)}."
        )
    _TRANSLATIONS[_parts[0]] = _parts

# Let the user change language from the top of the sidebar.
st.sidebar.selectbox(
    "🌐 Website language / भाषा",
    LANGUAGES,
    index=0,
    key="citrus_website_language",
)

def _citrus_language_index():
    return LANGUAGES.index(
        st.session_state.get("citrus_website_language", "English")
    )

def _citrus_translate_text(value):
    if not isinstance(value, str) or "<style>" in value:
        return value
    index = _citrus_language_index()
    if index == 0:
        return value
    # Longer phrases go first so small phrases cannot break a full sentence.
    for _english in sorted(_TRANSLATIONS, key=len, reverse=True):
        _localized = _TRANSLATIONS[_english][index]
        if _english in value:
            value = value.replace(_english, _localized)
    return value

def _citrus_translate_value(value):
    if isinstance(value, str):
        return _citrus_translate_text(value)
    if isinstance(value, list):
        return [_citrus_translate_value(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_citrus_translate_value(item) for item in value)
    if isinstance(value, dict):
        return {
            key: _citrus_translate_value(item)
            for key, item in value.items()
        }
    return value

# Localize Streamlit's visible labels, messages, captions, tabs and HTML.
# Model outputs and non-text objects pass through unchanged.
from streamlit.delta_generator import DeltaGenerator

_CITRUS_METHODS = (
    "markdown", "title", "header", "subheader", "caption", "write", "text",
    "success", "warning", "error", "info", "metric", "file_uploader",
    "checkbox", "button", "tabs", "spinner", "image", "expander",
    "download_button",
)

def _citrus_wrap_method(original):
    if getattr(original, "_citrus_i18n_wrapped", False):
        return original

    def _wrapped(self, *args, **kwargs):
        translated_args = _citrus_translate_value(args)
        translated_kwargs = _citrus_translate_value(kwargs)
        return original(self, *translated_args, **translated_kwargs)

    _wrapped._citrus_i18n_wrapped = True
    return _wrapped

def _citrus_wrap_function(original):
    if getattr(original, "_citrus_i18n_wrapped", False):
        return original

    def _wrapped(*args, **kwargs):
        translated_args = _citrus_translate_value(args)
        translated_kwargs = _citrus_translate_value(kwargs)
        return original(*translated_args, **translated_kwargs)

    _wrapped._citrus_i18n_wrapped = True
    return _wrapped

for _method_name in _CITRUS_METHODS:
    _method = getattr(DeltaGenerator, _method_name, None)
    if callable(_method):
        setattr(
            DeltaGenerator,
            _method_name,
            _citrus_wrap_method(_method),
        )

    _function = getattr(st, _method_name, None)
    if callable(_function):
        setattr(st, _method_name, _citrus_wrap_function(_function))
# CITRUS_I18N_END


